@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {}

class Subdivision {}

class Employee {
  + name : string
}

class Customer {
  + name : string
}

abstract class Account {
  + accountNumber : int
  + balance : double
  + creditOrOverdraftLimit : double
  + interestRate : float
  + monthlyFee : float
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class CreditCard {}

class Privilege {}

class Manager {}

Manager "1" -- "1" Division : manages

Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
Division "1" -- "*" Employee : has

Customer "*" -- "1" Employee : personal banker

Customer "1" -- "*" Account : opens at

Account "1" -- "*" Privilege : has

Account "1" -- "0..1" MortgageAccount : is a
Account "1" -- "0..1" CheckingAccount : is a
Account "1" -- "0..1" CreditCardAccount : is a

CreditCardAccount "1" -- "*" CreditCard : has secondary

Account "*" -- "*" Customer : joint account

@enduml

